/**
 * Jinx Heretic + Lleech: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Heretic
 * Wiki: https://wiki.bloodontheclocktower.com/Lleech
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { jinxRulesBetween, jinxSetupWarnings, scriptJinxes } from '#lib/core/rules/jinxes.ts';

describe('Heretic + Lleech jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'heretic', 'lleech');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('heretic')?.name).toBe('Heretic');
		expect(data.byId.get('lleech')?.name).toBe('Lleech');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['heretic', 'lleech'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['heretic'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['lleech'])).not.toContain(jinx);
	});

	// The Heretic's Related Jinxes: only one of the Heretic and the Lleech may be in play.
	it('is data in the Heretic rules: only one of the two may be in play', () => {
		expect(jinxRulesBetween('heretic', 'lleech')).toEqual({ exclusive: true });
		expect(jinxRulesBetween('lleech', 'heretic')).toEqual({ exclusive: true });
	});

	it('warns at setup when both are chosen, and not when one is', () => {
		const jinxes = scriptJinxes(data.jinxes, ['heretic', 'lleech', 'chef']);
		expect(jinxes.map((j) => j.exclusive)).toEqual([true]);
		expect(jinxSetupWarnings(jinxes, ['heretic', 'lleech'])).toHaveLength(1);
		expect(jinxSetupWarnings(jinxes, ['heretic', 'chef'])).toEqual([]);
	});
});
